import{_ as n,a0 as o,w as p,s as r,ao as d,I as l,x as i,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何在 Kali Linux 上安裝 SSH 服務 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kali Linux 上安裝 SSH 服務 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kali Linux 上安裝 SSH 服務 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kali Linux 上安裝 SSH 服務 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170121 How to install SSH  secure shell  service on Kali Linux","title":"如何在 Kali Linux 上安裝 SSH 服務","tag":"201702","desc":""},"relativePath":"201702/20170121 How to install SSH  secure shell  service on Kali Linux.md","filePath":"[post].md"}'),h={name:"201702/20170121 How to install SSH  secure shell  service on Kali Linux.md"};function g(u,s,c,k,b,f){const e=o("Link");return p(),r("div",null,[s[13]||(s[13]=d(`<h1 id="如何在-kali-linux-上安裝-ssh-服務" tabindex="-1">如何在 Kali Linux 上安裝 SSH 服務 <a class="header-anchor" href="#如何在-kali-linux-上安裝-ssh-服務" aria-label="Permalink to “如何在 Kali Linux 上安裝 SSH 服務”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p><strong>目的</strong></p><p>我們的目的是 Kali Linux 上安裝 SSH（安全 shell）。</p><p><strong>要求</strong></p><p>你需要有特權訪問你的 Kali Linux 安裝或者 Live 系統。</p><p><strong>困難程度</strong></p><p>很容易！</p><p><strong>慣例</strong></p><ul><li><code>#</code> - 給定命令需要以 root 用户權限運行或者使用 <code>sudo</code> 命令</li><li><code>$</code> - 給定命令以常規權限用户運行</li></ul><h3 id="指導" tabindex="-1">指導 <a class="header-anchor" href="#指導" aria-label="Permalink to “指導”">​</a></h3><p><strong>安裝 SSH</strong></p><p>從終端使用 <code>apt-get</code> 命令安裝 SSH 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt-get update</span></span>
<span class="line"><span># apt-get install ssh</span></span></code></pre></div><p><strong>啓用和開始使用 SSH</strong></p><p>為了確保安全 shell 能夠使用，在重啓系統後使用 <code>systemctl</code> 命令來啓用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable ssh</span></span></code></pre></div><p>在當前對話執行中使用 SSH:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># service ssh start</span></span></code></pre></div><p><strong>允許 SSH Root 訪問</strong></p><p>默認情況下 SSH 不允許以 root 用户登錄，因此將會出現下面的錯誤提示信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Permission denied, please try again.</span></span></code></pre></div><p>為了通過 SSH 進入你的 Kali Linux 系統，你可以有兩個不同的選擇。第一個選擇是創建一個新的非特權用户然後使用它的身份來登錄。第二個選擇，你可以以 root 用户訪問 SSH 。為了實現這件事，需要在SSH 配置文件 <code>/etc/ssh/sshd_config</code> 中插入下面這些行內容或對其進行編輯：</p><p>將</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#PermitRootLogin prohibit-password</span></span></code></pre></div><p>改為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PermitRootLogin yes</span></span></code></pre></div><p><img src="https://linuxconfig.org/images/enable-root-ssh-login-kali-linux.jpg" alt="kali linux enable ssh root access"></p><p>對 <code>/etc/ssh/sshd_config</code> 進行更改以後，需在以 root 用户登錄 SSH 前重啓 SSH 服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># service ssh restart</span></span></code></pre></div><hr>`,31)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux"},{default:a(()=>[...s[0]||(s[0]=[i("https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=i("作者：",-1)),t(e,{href:"https://linuxconfig.org/how-to-install-ssh-secure-shell-service-on-kali-linux"},{default:a(()=>[...s[2]||(s[2]=[i("Lubos Rendek",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),t(e,{href:"https://github.com/ucasFL"},{default:a(()=>[...s[3]||(s[3]=[i("ucasFL",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const C=n(h,[["render",g]]);export{m as __pageData,C as default};
